1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace Tests\Feature\Tags;
6	
7	use App\Models\Category1;
8	use App\Models\User;
9	use AtrioTeam\DigitalHub\Pim\Filament\Tables\DigitalHubTableMacro;
10	use AtrioTeam\DigitalHub\Tags\Enum\TagTarget;
11	use AtrioTeam\DigitalHub\Tags\Filament\Resources\Pages\ListTagGroups;
12	use AtrioTeam\DigitalHub\Tags\Models\TagGroup;
13	use Filament\Facades\Filament;
14	use Illuminate\Foundation\Testing\RefreshDatabase;
15	use Livewire\Livewire;
16	use Tests\TestCase;
17	
18	/**
19	 * Aggancio applicativo dei gruppi tag alla Destinazione (Category1): campo
20	 * category_1_id iniettato nel form del core via TagGroupForm::extraComponentsUsing
21	 * (vedi AppServiceProvider::extendTagGroups). Regressione: il select deve essere
22	 * nominato con la FK, perché l'EditAction in modale salva con
23	 * $record->update($data) e uno state 'category1' finirebbe in SQL come colonna
24	 * inesistente.
25	 */
26	class TagGroupCategory1EditTest extends TestCase
27	{
28	    use RefreshDatabase;
29	
30	    protected function setUp(): void
31	    {
32	        parent::setUp();
33	
34	        // registrato normalmente dal boot del DigitalHubPlugin, che nei test
35	        // Livewire non viene eseguito
36	        DigitalHubTableMacro::register();
37	    }
38	
39	    public function test_edit_action_saves_category_1_id(): void
40	    {
41	        $this->actingAs(User::factory()->create());
42	        Filament::setCurrentPanel('admin');
43	
44	        $indoor = Category1::create(['name' => ['it' => 'Indoor']]);
45	        $group = TagGroup::create([
46	            'name' => ['it' => 'Tag Tessuti', 'en' => 'Fabric tags'],
47	            'entity_type' => 'fabric',
48	            'target' => TagTarget::Entity,
49	        ]);
50	
51	        Livewire::test(ListTagGroups::class)
52	            ->callTableAction('edit', $group, data: [
53	                'category_1_id' => $indoor->id,
54	            ])
55	            ->assertHasNoTableActionErrors();
56	
57	        $this->assertSame($indoor->id, $group->refresh()->category_1_id);
58	        $this->assertTrue($group->category1->is($indoor));
59	    }
60	
61	    public function test_edit_action_allows_clearing_category_1_id(): void
62	    {
63	        $this->actingAs(User::factory()->create());
64	        Filament::setCurrentPanel('admin');
65	
66	        $indoor = Category1::create(['name' => ['it' => 'Indoor']]);
67	        $group = TagGroup::create([
68	            'name' => ['it' => 'Tag Tessuti', 'en' => 'Fabric tags'],
69	            'entity_type' => 'fabric',
70	            'target' => TagTarget::Entity,
71	            'category_1_id' => $indoor->id,
72	        ]);
73	
74	        Livewire::test(ListTagGroups::class)
75	            ->callTableAction('edit', $group, data: [
76	                'category_1_id' => null,
77	            ])
78	            ->assertHasNoTableActionErrors();
79	
80	        $this->assertNull($group->refresh()->category_1_id);
81	    }
82	}
